// NIGHTLY 3h sáng — (1) kéo đơn VỪA CẬP NHẬT (3 ngày) + (2) 5 stream nặng/tĩnh.
//
// (1) Orders API CÓ lọc theo thời điểm cập nhật: `updateStatus` nhận TÊN TRƯỜNG THỜI GIAN
//     (`inserted_at` mặc định | `updated_at` | `paid_at` = lúc sàn đối soát | `partner_inserted_at`).
//     Đo thật 2026-07-14 (shop TikTok, cửa sổ 3 ngày): mặc định trả 1 đơn; `updateStatus=updated_at`
//     trả 4 đơn — trong đó 3 đơn TẠO từ 25/06–07/07 nhưng vừa được sửa trong cửa sổ.
//     Kết luận cũ "API CHỈ lọc inserted_at" là SAI: test cũ truyền `updateStatus=0/1`, mà 0/1 là
//     MÃ TRẠNG THÁI ĐƠN (Mới / Đã xác nhận), không phải tên trường.
//     ⇒ Bỏ vòng re-sync 45 ngày (45 cửa sổ × 3 shop = 135 request/đêm) → 1 cửa sổ 3 ngày/shop.
//     Đơn đổi sang HOÀN/HUỶ và đơn được sàn CẬP NHẬT PHÍ (5% tạm → phí thật cao hơn hẳn mức tạm) đều lọt cửa sổ này.
//
// (1b) LƯỚI AN TOÀN — CHỦ NHẬT (giờ VN) quét thêm 45 ngày theo `inserted_at`: bù trường hợp app/n8n
//      chết dài ngày, hoặc Pancake KHÔNG cập nhật `updated_at` cho một loại thay đổi nào đó (chưa
//      chứng minh được là nó luôn cập nhật). Rẻ: 1 lần/tuần. Bronze dedupe theo hash ⇒ chồng lấn miễn phí.
//
// (2) customers/purchases/transactions/inventory_histories/reverse_order đổi chậm → 1 lần/đêm là đủ;
//     kéo mỗi 30' (customers hàng trăm trang) sẽ ăn rate-limit ban.
//
// (3) TỪ 2026-07-28 lượt này còn kéo `products` + `products/variations` — trước đây việc đó do
//     workflow 30' làm. Lịch 30' ĐÃ TẮT (chỉ còn chạy khi bấm "Đồng bộ ngay" trong app): webhook
//     Pancake nay lo phần TƯƠI (đơn hàng + tồn kho theo thời gian thực) nên không cần gọi API 48
//     lượt/ngày nữa. Hệ quả BẮT BUỘC nhớ: đây là lượt DUY NHẤT làm mới giá vốn/sản phẩm mỗi ngày,
//     và cũng là lượt tạo điều kiện cho bước vá tồn ở cuối (chốt chặn của endpoint đòi có lượt kéo
//     `products` shop kho trong 2 giờ) ⇒ products PHẢI đứng trước trong STREAMS, đừng đảo xuống sau.
// Land TEXT THÔ vào Bronze (KHÔNG để n8n parse JSON). SỬA khối CONFIG rồi Execute.
/**
 * Khoá lấy từ node "Lấy khoá từ bảng Setting" (mỗi dòng = 1 cặp key/value của bảng `app."Setting"`).
 * Để khoá trong bảng thay vì viết thẳng vào đây: mở bảng là xem được, đổi khoá chỉ sửa 1 ô, và
 * file workflow trong repo khớp tuyệt đối bản đang chạy nên diff được.
 */
const KHOA = Object.fromEntries($input.all().map((i) => [i.json.key, i.json.value]));
const KHOA_THIEU = ["n8nAppUrl","n8nIngestSecret","pancakeApiKeyKho","pancakeApiKeyShopee","pancakeApiKeyTiktok","pancakeShopIdKho","pancakeShopIdShopee","pancakeShopIdTiktok"].filter((k) => !KHOA[k]);
if (KHOA_THIEU.length) {
  throw new Error(
    `THIẾU KHOÁ trong bảng app."Setting": ${KHOA_THIEU.join(", ")}. Thêm dòng key/value tương ứng rồi ` +
      `chạy lại — không cần đụng file cấu hình hay dựng lại container.`
  );
}

const CONFIG = {
  base: "https://pos.pages.fm/api/v1",
  appUrl: KHOA.n8nAppUrl,              // go-live: http://hogikids-app:3000 | test: http://<IP-Tailscale-dev>:3000
  ingestSecret: KHOA.n8nIngestSecret,  // == INGEST_SECRET trong .env app
  // Shop ID đọc từ bảng Setting (clone-and-go 2026-08-21) — cùng nguồn với app; bản clone điền id CỦA HỌ ở /cai-dat.
  shops: {
    kho:    { id: KHOA.pancakeShopIdKho,    key: KHOA.pancakeApiKeyKho },
    shopee: { id: KHOA.pancakeShopIdShopee, key: KHOA.pancakeApiKeyShopee },
    tiktok: { id: KHOA.pancakeShopIdTiktok, key: KHOA.pancakeApiKeyTiktok },
  },
};

// `shops` = shop THẬT SỰ có dữ liệu cho stream đó (Task 0 discovery) — purchases chỉ có ở shop kho;
// transactions + reverse_order chỉ có ở 2 shop marketplace (Shopee/TikTok).
const STREAMS = [
  // THỨ TỰ CỐ Ý: products (+ variations) TRƯỚC orders — OrderItem tra Variant theo SKU để lấy giá
  // vốn, chưa có Variant thì item mồ côi và COGS = 0.
  { name: "products",                  shops: ["kho", "shopee", "tiktok"] },
  { name: "products/variations",       shops: ["kho", "shopee", "tiktok"] },
  { name: "orders",                    shops: ["kho", "shopee", "tiktok"], dated: true },
  { name: "purchases",                 shops: ["kho"] },
  { name: "inventory_histories",       shops: ["kho", "shopee", "tiktok"] },
  { name: "transactions",              shops: ["shopee", "tiktok"] },
  { name: "marketplace/reverse_order", shops: ["shopee", "tiktok"] },
  { name: "customers",                 shops: ["kho", "shopee", "tiktok"] },
];

const http = this.helpers.httpRequest;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const nowSec = Math.floor(Date.now() / 1000);

// Chủ nhật tính theo GIỜ VN (không theo TZ container — container có thể chạy UTC).
const vnWeekday = new Intl.DateTimeFormat("en-US", { timeZone: "Asia/Ho_Chi_Minh", weekday: "short" }).format(
  new Date(nowSec * 1000)
);
const isSunday = vnWeekday === "Sun";

/**
 * Mỗi "lượt" = 1 cửa sổ thời gian + 1 cách lọc. Đơn kéo theo `updated_at` nên KHÔNG cần chẻ nhỏ
 * cửa sổ (3 ngày đơn vừa-đổi là vài chục đơn, phân trang lo được).
 */
const ORDER_PASSES = [
  { updateStatus: "updated_at", days: 3, label: "đơn vừa cập nhật 3 ngày" },
];
if (isSunday) {
  ORDER_PASSES.push({ updateStatus: null, days: 45, label: "LƯỚI AN TOÀN chủ nhật: 45 ngày theo inserted_at" });
}

const results = [];
const errors = [];
// Shop bị Pancake TỪ CHỐI XÁC THỰC (401/403) — không đụng tới nữa trong lượt chạy này.
const authDeadShops = new Set();

/** Rút total_pages bằng regex trên TEXT THÔ — TUYỆT ĐỐI KHÔNG JSON.parse (int64 sẽ hỏng). */
function totalPagesOf(text) {
  const m = text.match(/"total_pages":\s*(\d+)/);
  return m ? Number(m[1]) : 1;
}

/** 401/403 = key sai/bị chặn. KHÁC hẳn lỗi mạng/rate-limit: thử lại chỉ làm tình hình tệ hơn. */
function isAuthError(err) {
  const code = (err && (err.httpCode || err.statusCode || (err.response && err.response.status))) || "";
  const msg = (err && err.message) || String(err);
  return String(code) === "401" || String(code) === "403" || /status code (401|403)/.test(msg);
}

/** GET 1 trang (TEXT thô) → POST thẳng sang app. Trả total_pages đọc được từ chuỗi thô. */
async function fetchAndLand(streamName, shopKey, win, page, updateStatus) {
  const shop = CONFIG.shops[shopKey];
  // Pancake KHÔNG nhất quán tham số phân trang: đa số stream nghe `page_number`, riêng
  // `inventory_histories` CHỈ nghe `page` — gửi page_number cho nó thì mọi trang đều trả về
  // trang 1 (mất sạch trang 2..N mà không hề báo lỗi). Gửi CẢ HAI, cùng giá trị.
  const qs = { api_key: shop.key, page_number: page, page: page, page_size: 100 };
  if (win) { qs.startDateTime = win.start; qs.endDateTime = win.end; }
  // `updateStatus` = TÊN TRƯỜNG mà startDateTime/endDateTime lọc theo. Bỏ trống ⇒ inserted_at.
  if (updateStatus) qs.updateStatus = updateStatus;
  // `encoding: "text"` LÀ BẮT BUỘC: trong n8n `json: false` CHỈ đổi header Accept — responseType của
  // axios chỉ được set từ `encoding`. Thiếu nó, axios VẪN JSON.parse body ⇒ int64 bị làm tròn (hỏng
  // khoá), regex total_pages trượt (chỉ kéo trang 1), và payload thành object ⇒ app trả 400.
  const text = await http({
    method: "GET",
    url: `${CONFIG.base}/shops/${shop.id}/${streamName}`,
    qs,
    json: false,
    encoding: "text",
  });
  // Chốt chặn: bản n8n nào đổi hành vi thì workflow KÊU TO, không âm thầm hỏng khoá.
  if (typeof text !== "string") {
    throw new Error("n8n trả về object, không phải TEXT thô — thiếu encoding:'text'. int64 sẽ hỏng.");
  }
  const totalPages = totalPagesOf(text);

  // Gửi NGUYÊN chuỗi thô sang app — app tự bung mảng/băm/dedupe, KHÔNG parse ở đây.
  const r = await http({
    method: "POST",
    url: `${CONFIG.appUrl}/api/ingest/raw`,
    json: true,
    headers: { Authorization: `Bearer ${CONFIG.ingestSecret}` },
    body: { stream: streamName, shopId: shop.id, payload: text },
  });
  results.push({
    stream: streamName, shop: shopKey, page, totalPages,
    filter: updateStatus || "inserted_at",
    landed: r && r.stats ? r.stats.landed : undefined,
    mode: r && r.stats ? r.stats.mode : undefined,
  });
  return totalPages;
}

/** Kéo hết mọi trang của 1 (stream, shop, cửa sổ, cách lọc). */
async function pullPages(streamName, shopKey, win, updateStatus) {
  let page = 1;
  let totalPages = 1;
  do {
    try {
      totalPages = await fetchAndLand(streamName, shopKey, win, page, updateStatus);
    } catch (err) {
      if (page === 1) {
        // Trang 1 hỏng ⇒ totalPages vẫn = 1 ⇒ do-while thoát ⇒ MẤT CẢ lượt này, không chỉ 1 trang.
        // Thử lại ĐÚNG 1 lần sau 2s; vẫn hỏng thì ghi lỗi RÕ RÀNG rồi đi tiếp.
        await sleep(2000);
        try {
          totalPages = await fetchAndLand(streamName, shopKey, win, page, updateStatus);
        } catch (err2) {
          errors.push({
            scope: win ? "CA_CUA_SO_BI_BO" : "CA_STREAM_BI_BO",
            stream: streamName, shop: shopKey, page, window: win || null,
            filter: updateStatus || "inserted_at",
            message: `BỎ QUA — stream "${streamName}", shop "${shopKey}", trang 1 lỗi 2 lần: ${(err2 && err2.message) || String(err2)}`,
          });
          // Sai key thì mọi lượt sau của shop này cũng sai — ngắt ngay, đừng bắn thêm.
          if (isAuthError(err2)) {
            authDeadShops.add(shopKey);
            return;
          }
        }
      } else {
        // Lỗi 1 trang lẻ (rate-limit / app 500) KHÔNG được giết cả lượt sync — ghi lỗi rồi chạy tiếp.
        // NHƯNG key bị chặn GIỮA CHỪNG (sau khi trang 1 đã qua) ⇒ mọi trang sau của shop cũng hỏng:
        // escalate (scope NẶNG + dừng shop) để C1 ném đỏ thay vì nuốt thành MOT_TRANG.
        if (isAuthError(err)) {
          authDeadShops.add(shopKey);
          errors.push({
            scope: "SHOP_CHET_XAC_THUC",
            stream: streamName, shop: shopKey, page, window: win || null,
            filter: updateStatus || "inserted_at",
            message: `BỎ QUA phần còn lại của shop "${shopKey}" — key bị chặn xác thực (401/403) giữa chừng ở trang ${page}.`,
          });
          return;
        }
        errors.push({
          scope: "MOT_TRANG",
          stream: streamName, shop: shopKey, page, window: win || null,
          filter: updateStatus || "inserted_at",
          message: (err && err.message) || String(err),
        });
      }
    }
    page++;
    await sleep(300); // né rate-limit Pancake
  } while (page <= totalPages && page <= 500); // chặn vòng lặp vô hạn nếu total_pages đọc sai
}

/** Kéo 1 stream cho 1 shop. Stream `dated` (orders) chạy theo ORDER_PASSES; còn lại kéo toàn bộ. */
async function pullStreamShop(streamName, shopKey, dated) {
  // CẦU DAO: key của shop này đã bị từ chối xác thực ⇒ DỪNG HẲN shop đó.
  // Không có cầu dao thì 1 key sai sẽ đẻ ra hàng loạt request hỏng ⇒ Pancake coi là lạm dụng và
  // chặn tạm key + IP vài giờ (đã xảy ra thật 2026-07-13).
  if (authDeadShops.has(shopKey)) {
    errors.push({
      scope: "SHOP_CHET_XAC_THUC",
      stream: streamName, shop: shopKey, page: 0, window: null,
      message: `BỎ QUA — shop "${shopKey}" đã bị Pancake từ chối xác thực (401/403). Kiểm tra lại api_key.`,
    });
    return;
  }

  if (!dated) {
    await pullPages(streamName, shopKey, null, null);
    return;
  }

  for (const pass of ORDER_PASSES) {
    const win = { start: nowSec - pass.days * 86400, end: nowSec };
    await pullPages(streamName, shopKey, win, pass.updateStatus);
    if (authDeadShops.has(shopKey)) return;
  }
}

for (const st of STREAMS) {
  for (const shopKey of st.shops) {
    await pullStreamShop(st.name, shopKey, !!st.dated);
  }
}

// VÁ TỒN KHO TỪ API — bước làm cho câu "API là CHUẨN" đúng với tồn kho.
// Vì sao cần: /api/ingest/raw chỉ dựng lại Silver cho sản phẩm VỪA đổi payload (Bronze dedupe theo
// hash) ⇒ một giá trị tồn sai do webhook ghi sẽ nằm lại vĩnh viễn nếu bên Pancake món đó không đổi
// gì thêm. Endpoint quét toàn bộ Bronze products dựng lại tồn. Nó TỪ CHỐI CHẠY (trả 500) nếu nhật
// ký đồng bộ không có lượt kéo `products` shop kho nào trong 2 giờ — nghĩa là lượt sync 30' đã chết,
// lúc đó đè tồn bằng ảnh Bronze cũ sẽ xoá mất số webhook đúng.
// Lỗi ở bước này KHÔNG giết ngay lượt nightly (dữ liệu đã land an toàn ở trên) nhưng được ghi vào
// `errors` với scope riêng ⇒ cuối lượt vẫn THROW để lượt chạy ĐỎ. Im lặng = tồn sai nằm lại mãi.
let vaTonKho;
try {
  const rv = await http({
    method: "POST",
    url: `${CONFIG.appUrl}/api/ingest/resync-products`,
    json: true,
    headers: { Authorization: `Bearer ${CONFIG.ingestSecret}` },
    body: {},
  });
  vaTonKho = rv && rv.stats ? rv.stats : rv;
} catch (err) {
  vaTonKho = { loi: String((err && err.message) || err) };
  // Scope RIÊNG ⇒ lượt chạy ĐỎ. Cố ý: ngoài n8n không còn chỗ nào báo bước này trượt (request
  // không tới app thì cũng không có SyncLog), mà trượt im lặng = tồn sai nằm lại vô thời hạn.
  errors.push({
    scope: "VA_TON_KHO",
    stream: "resync-products", shop: "-", page: 0, window: null,
    message: `vá tồn kho lỗi: ${String((err && err.message) || err)}`,
  });
}

// ĐỐI SOÁT ĐƠN CÒN DỞ — nhặt đơn đã land Bronze mà chưa dựng xong Sổ. Đặt SAU vá tồn kho, TRƯỚC
// bước chặn lỗi. Vì sao cần: một tiến trình chết giữa "land Bronze" và "ghi Sổ" để lại đơn kẹt mà
// lượt gửi lại đúng trang TỰ CHỮA được (route dò seenIds), nhưng đơn đã yên vị thì Pancake không bắn lại nên không lượt nào chạm ⇒ doanh thu
// thiếu âm thầm. Endpoint quét các đơn CHƯA đóng dấu kết cục rồi dựng nốt.
// Mã HTTP nói "phép đối soát có CHẠY được không", KHÔNG nói "dữ liệu có sạch không": 200 kể cả khi
// còn `pending`/`needs_attention` (đó là TRẠNG THÁI, panel /cai-dat hiển thị, không phải sync hỏng);
// MỌI request lỗi/non-2xx (bearer sai 401, đang phục hồi 503, lỗi hệ thống 500, lỗi mạng) đều vào catch ⇒ scope riêng ⇒ lượt ĐỎ; riêng 500 nghĩa: không đối soát được đáng tin cậy.
let doiSoatDon;
try {
  const rd = await http({
    method: "POST",
    url: `${CONFIG.appUrl}/api/ingest/reconcile-orders`,
    json: true,
    headers: { Authorization: `Bearer ${CONFIG.ingestSecret}` },
    body: {},
  });
  doiSoatDon = rd && rd.stats ? rd.stats : rd;
} catch (err) {
  doiSoatDon = { loi: String((err && err.message) || err) };
  errors.push({
    scope: "DOI_SOAT_DON",
    stream: "reconcile-orders", shop: "-", page: 0, window: null,
    message: `đối soát đơn còn dở lỗi: ${String((err && err.message) || err)}`,
  });
}

// CHẶN NUỐT LỖI: lỗi NẶNG (mất dữ liệu — khác MOT_TRANG) phải làm workflow ĐỎ.
// Thiếu bước này thì 1 shop bị chặn api_key khiến n8n báo XANH mà doanh thu thiếu âm thầm (Pancake là nguồn duy nhất).
const nang = errors.filter((e) => e.scope !== "MOT_TRANG");
if (nang.length) {
  const nl = String.fromCharCode(10); // xuống dòng cho dễ đọc trong panel lỗi n8n
  throw new Error(
    nang.length + " lượt BỊ BỎ (mất dữ liệu):" + nl +
    nang.map((e) => "- [" + e.scope + "] " + e.stream + "/" + e.shop + ": " + e.message).join(nl)
  );
}

return [{ json: { vnWeekday, isSunday, passes: ORDER_PASSES.map((p) => p.label), results, vaTonKho, doiSoatDon, errors } }];
